def _open_stream_session(paths, quiesce):
    """Pin every member's inode and take the snapshot policy decision.

    Mirrors read_linked_logs' marker gate per member: the descriptor
    pins one inode, the commit marker is rechecked after the open, and
    the snapshot covers exactly the bytes present at that moment.
    Returns (fds, ends, post_flags).
    """
    fds = []
    try:
        ends = []
        posts = []
        for path in paths:
            marker = _commit_marker_path(path)
            post = os.path.exists(marker)
            fd = _open_path_wait(path, quiesce)
            try:
                st = os.fstat(fd.fileno())
            except OSError:
                fd.close()
                raise
            if not post and os.path.exists(marker):
                post = True
            fds.append(fd)
            ends.append(st.st_size)
            posts.append(post)
    except BaseException:
        for fd in fds:
            fd.close()
        raise
    return fds, ends, posts
